-- Seed: the WisePlug gadget and reference signatures for 7 common household
-- appliances (230 V, 60 Hz Philippine mains). These are typical ranges for
-- matching; the plug still learns each real appliance's own signature and
-- typical runtime from its first 7 uses. Apparent and reactive power bounds
-- are generated by Postgres from the power and PF bounds.
--
-- Owner is set by the link-account function on first sign-in.

insert into public.devices (id, name) values ('gadget-1', 'WisePlug dual outlet')
on conflict (id) do nothing;

insert into public.appliances
  (device_id, name, appliance_type,
   min_power, target_power, max_power,
   min_current, target_current, max_current,
   min_pf, target_pf, max_pf,
   max_runtime_mins, source)
values
  -- Motor with run capacitor: near-unity PF, some reactive power.
  ('gadget-1', 'Electric Fan',         'Electric fan',   35,   55,   75,  0.160, 0.250, 0.340,  0.85, 0.95, 1.00,   480, 'seed'),
  -- Heating element while cooking (keep-warm draws only ~40-60 W).
  ('gadget-1', 'Rice Cooker',          'Rice cooker',   450,  600,  750,  1.950, 2.620, 3.300,  0.95, 1.00, 1.00,    90, 'seed'),
  -- Resistive heater, cycles on its thermostat.
  ('gadget-1', 'Flat Iron',            'Flat iron',     900, 1100, 1300,  3.900, 4.800, 5.700,  0.95, 1.00, 1.00,    60, 'seed'),
  -- Below the firmware's 10 A MAX_CURRENT_A trip (a 2.2 kW kettle would trip it).
  ('gadget-1', 'Electric Kettle',      'Kettle',       1500, 1750, 2000,  6.500, 7.700, 8.900,  0.95, 1.00, 1.00,    15, 'seed'),
  -- Switch-mode supply: low PF, large reactive share.
  ('gadget-1', 'LED TV',               'TV',             40,   75,  110,  0.250, 0.475, 0.700,  0.45, 0.60, 0.75,   360, 'seed'),
  ('gadget-1', 'Laptop/Phone Charger', 'Charger',         5,   45,   90,  0.040, 0.345, 0.650,  0.30, 0.55, 0.80,   300, 'seed'),
  -- Compressor cycles on and off all day; long limit so it is never cut off by mistake.
  ('gadget-1', 'Refrigerator',         'Refrigerator',   80,  140,  200,  0.450, 0.825, 1.200,  0.60, 0.75, 0.90,  1440, 'seed');
